<?php
 namespace Pterodactyl\Services\Dezerx\DayZ; use Throwable; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Pterodactyl\Services\Dezerx\Addons; class DayZWorkshop { public const APP_ID = 221100; private const API = 'https://api.steampowered.com'; private const COMMUNITY = 'https://steamcommunity.com'; private const PER_PAGE = 18; private const DETAILS_TTL = 1800; private const SEARCH_TTL = 600; private const REQUIRES_TTL = 21600; public const ID = '/^[0-9]{1,20}$/'; public function configured(): bool { return $this->key() !== ''; } private function key(): string { $own = trim((string) (Addons::get(Addons::DAYZ_MOD_MANAGER)['steam_api_key'] ?? '')); return $own !== '' ? $own : trim((string) (config('services.steam.key') ?? '')); } private function http() { return Http::withHeaders(['User-Agent' => 'Mozilla/5.0 (compatible; DezerX-Stark/1.0)']) ->timeout(12) ->connectTimeout(5); } public static function idFrom(string $input): ?string { $input = trim($input); if (preg_match(self::ID, $input) === 1) { return ltrim($input, '0') ?: null; } if (preg_match('~steamcommunity\.com/(?:sharedfiles|workshop)/filedetails/?\?(?:[^#]*&)?id=([0-9]{1,20})~i', $input, $match) === 1) { return ltrim($match[1], '0') ?: null; } return null; } public function details(array $ids): array { $ids = array_values(array_unique(array_filter(array_map('strval', $ids), fn ($id) => preg_match(self::ID, $id) === 1))); $out = []; $missing = []; foreach ($ids as $id) { $cached = Cache::get("dezerx:dayz:item:{$id}"); if (is_array($cached)) { $out[$id] = $cached; } else { $missing[] = $id; } } foreach (array_chunk($missing, 50) as $chunk) { $form = ['itemcount' => count($chunk)]; foreach ($chunk as $index => $id) { $form["publishedfileids[{$index}]"] = $id; } try { $response = $this->http()->asForm()->post(self::API . '/ISteamRemoteStorage/GetPublishedFileDetails/v1/', $form); } catch (Throwable) { continue; } foreach ((array) $response->json('response.publishedfiledetails') as $raw) { $item = $this->item(is_array($raw) ? $raw : []); if ($item !== null) { Cache::put("dezerx:dayz:item:{$item['id']}", $item, self::DETAILS_TTL); $out[$item['id']] = $item; } } } return $out; } private function item(array $raw): ?array { $id = (string) ($raw['publishedfileid'] ?? ''); if ((int) ($raw['result'] ?? 0) !== 1 || preg_match(self::ID, $id) !== 1 || (int) ($raw['consumer_app_id'] ?? 0) !== self::APP_ID) { return null; } return [ 'id' => $id, 'title' => mb_substr(trim((string) ($raw['title'] ?? '')), 0, 120) ?: "Workshop item {$id}", 'description' => self::plain((string) ($raw['description'] ?? '')), 'preview' => self::https((string) ($raw['preview_url'] ?? '')), 'size' => (int) ($raw['file_size'] ?? 0), 'updatedAt' => (int) ($raw['time_updated'] ?? 0) ?: null, 'subscriptions' => (int) ($raw['subscriptions'] ?? $raw['lifetime_subscriptions'] ?? 0), 'tags' => array_values(array_filter(array_map(fn ($tag) => (string) ($tag['tag'] ?? ''), (array) ($raw['tags'] ?? [])))), 'url' => self::COMMUNITY . "/sharedfiles/filedetails/?id={$id}", 'collection' => false, ]; } public function search(string $query, int $page): array { $query = mb_substr(trim($query), 0, 100); $page = max(1, min(50, $page)); $error = null; $ids = Cache::remember('dezerx:dayz:search:' . md5(mb_strtolower($query) . '|' . $page . '|' . ($this->configured() ? 'key' : 'page')), self::SEARCH_TTL, function () use ($query, $page, &$error) { try { return $this->configured() ? $this->searchApi($query, $page) : $this->searchPage($query, $page); } catch (Throwable) { $error = 'The Steam Workshop could not be reached right now.'; return null; } }); if ($ids === null) { Cache::forget('dezerx:dayz:search:' . md5(mb_strtolower($query) . '|' . $page . '|' . ($this->configured() ? 'key' : 'page'))); } $details = $this->details($ids ?? []); return [ 'results' => array_values(array_filter(array_map(fn ($id) => $details[$id] ?? null, $ids ?? []))), 'page' => $page, 'hasMore' => count($ids ?? []) >= self::PER_PAGE, 'error' => $error, ]; } private function searchApi(string $query, int $page): array { $response = $this->http()->get(self::API . '/IPublishedFileService/QueryFiles/v1/', [ 'key' => $this->key(), 'appid' => self::APP_ID, 'query_type' => $query === '' ? 9 : 12, 'search_text' => $query, 'page' => $page, 'numperpage' => self::PER_PAGE, 'filetype' => 0, 'return_details' => 0, ]); if ($response->failed()) { throw new \RuntimeException('Steam refused the search (' . $response->status() . ')'); } return array_values(array_filter(array_map( fn ($row) => (string) ($row['publishedfileid'] ?? ''), (array) $response->json('response.publishedfiledetails'), ), fn ($id) => preg_match(self::ID, $id) === 1)); } private function searchPage(string $query, int $page): array { $response = $this->http()->get(self::COMMUNITY . '/workshop/browse/', [ 'appid' => self::APP_ID, 'searchtext' => $query, 'browsesort' => $query === '' ? 'totaluniquesubscribers' : 'textsearch', 'actualsort' => $query === '' ? 'totaluniquesubscribers' : 'textsearch', 'section' => 'readytouseitems', 'p' => $page, ]); if ($response->failed()) { throw new \RuntimeException('Steam refused the search page (' . $response->status() . ')'); } preg_match_all('~sharedfiles/filedetails/\?id=([0-9]{1,20})~', $response->body(), $matches); return array_slice(array_values(array_unique($matches[1] ?? [])), 0, self::PER_PAGE); } public function requires(string $id): array { if (preg_match(self::ID, $id) !== 1) { return []; } $found = Cache::get("dezerx:dayz:requires:{$id}"); if (is_array($found)) { return $found; } try { $found = $this->configured() ? $this->requiresApi($id) : $this->requiresPage($id); } catch (Throwable) { return []; } $found = array_values(array_unique(array_filter($found, fn ($child) => $child !== $id && preg_match(self::ID, $child) === 1))); Cache::put("dezerx:dayz:requires:{$id}", $found, self::REQUIRES_TTL); return $found; } private function requiresApi(string $id): array { $response = $this->http()->get(self::API . '/IPublishedFileService/GetDetails/v1/', [ 'key' => $this->key(), 'publishedfileids[0]' => $id, 'includechildren' => 1, ]); if ($response->failed()) { throw new \RuntimeException('Steam refused the details (' . $response->status() . ')'); } return array_map( fn ($child) => (string) ($child['publishedfileid'] ?? ''), (array) $response->json('response.publishedfiledetails.0.children'), ); } private function requiresPage(string $id): array { $response = $this->http()->get(self::COMMUNITY . '/sharedfiles/filedetails/', ['id' => $id]); if ($response->failed()) { throw new \RuntimeException('Steam refused the item page (' . $response->status() . ')'); } $body = $response->body(); $start = strpos($body, 'id="RequiredItems"'); if ($start === false) { return []; } $block = substr($body, $start, 6000); preg_match_all('~filedetails/\?id=([0-9]{1,20})~', $block, $matches); return $matches[1] ?? []; } public function collection(string $id): ?array { if (preg_match(self::ID, $id) !== 1) { return null; } try { $response = $this->http()->asForm()->post(self::API . '/ISteamRemoteStorage/GetCollectionDetails/v1/', [ 'collectioncount' => 1, 'publishedfileids[0]' => $id, ]); } catch (Throwable) { return null; } $entry = (array) $response->json('response.collectiondetails.0'); if ((int) ($entry['result'] ?? 0) !== 1) { return null; } return array_values(array_filter(array_map( fn ($child) => (string) ($child['publishedfileid'] ?? ''), (array) ($entry['children'] ?? []), ), fn ($child) => preg_match(self::ID, $child) === 1)); } private static function plain(string $text): string { $text = preg_replace('~\[url=[^\]]*\](.*?)\[/url\]~is', '$1', $text) ?? $text; $text = preg_replace('~\[/?[a-z0-9*]+(?:=[^\]]*)?\]~i', ' ', $text) ?? $text; $text = trim(preg_replace('/\s+/u', ' ', strip_tags($text)) ?? ''); return mb_strlen($text) > 220 ? rtrim(mb_substr($text, 0, 217)) . '…' : $text; } private static function https(string $url): ?string { $url = trim($url); return str_starts_with($url, 'https://') ? $url : (str_starts_with($url, 'http://') ? 'https://' . substr($url, 7) : null); } } 